// Deterministic redelivery model — no clock, no randomness.
// A single message needs `processMs` to finish. While it is in flight,
// every time the visibility window elapses the broker hands it to a NEW
// consumer, which charges Stripe once. The first consumer to actually
// reach processMs acks (DeleteMessage) and the message stops redelivering.
function charges(visMs, processMs) {
  let charged = 0;          // total Stripe calls (one per delivery)
  let t = 0;                // clock, ms
  // The original consumer started at t=0 and will ack at t=processMs.
  charged++;                // first delivery charges once
  // Each subsequent visibility expiry before processMs = a redelivery.
  for (let next = visMs; next < processMs; next += visMs) {
    charged++;              // a new consumer picks it up and charges again
  }
  return charged;
}
const PROCESS = 75000; // 75s processing time
for (const vis of [30000, 90000, 450000]) {
  console.log('vis=' + (vis / 1000) + 's -> charges=' + charges(vis, PROCESS));
}
console.log('rule: visibility timeout >= 6x processing time => exactly 1 charge');

