// SQS handed us this stream: msg-7a3f redelivered 3x (timeout < processing),
// plus two genuinely distinct messages. Make `handle` idempotent so each
// message id is charged at most ONCE, while distinct ids still each charge.
const deliveries = [
  { id: 'msg-7a3f', order: 'O-123', cents: 5000 },
  { id: 'msg-7a3f', order: 'O-123', cents: 5000 },
  { id: 'msg-9b2c', order: 'O-456', cents: 1200 },
  { id: 'msg-7a3f', order: 'O-123', cents: 5000 },
  { id: 'msg-4d1e', order: 'O-789', cents: 3300 },
];
let chargeCalls = 0;
function chargeStripe(/* id, cents */) { chargeCalls++; }

// TODO: make this idempotent. Right now it charges on every delivery.
function handle(msg) {
  chargeStripe(msg.id, msg.cents);
}

for (const d of deliveries) handle(d);
console.log('chargeCalls=' + chargeCalls);
console.log('distinctCharged=3');
